window.LANES={"loud":{"name":"Loud","kindWord":"Websites","kind":"site"},"motion":{"name":"Motion","kindWord":"Websites","kind":"site"},"quiet":{"name":"Quiet","kindWord":"Websites","kind":"site"},"direct":{"name":"Direct","kindWord":"Websites","kind":"site"},"system":{"name":"The system","kindWord":"The system","kind":"tool"}};
window.BUILDS=[{"n":1,"slug":"atelier-voss","kind":"site","lane":"quiet","trade":"Architecture practice","mobile":true,"group":"Websites · Quiet","name":"Atelier Voss","biz":"Architecture practice","c":"#14508c","sheet":"#DEE7EF","cInk":"#FFFFFF","cText":"#14508C","short":"A studio site with no photographs at all.","long":"The entire site is illustrated in hand-authored technical drawings: elevations that draw themselves in, hatched plans, dimension lines, poché section cuts. Cyanotype blue, and a real six-cell title block for a masthead.","proves":"What a site looks like when nothing on it came from a stock library.","tags":["All-SVG drawings","Pinned sequence","Title block"],"tk":"creative","show":[{"scrollBy":2600,"dur":5200,"say":"Scroll: the drawings draw themselves"}]},{"n":2,"slug":"cadence","kind":"site","lane":"direct","trade":"Software company","mobile":true,"group":"Websites · Direct","name":"Cadence","biz":"Field-ops software","c":"#FFB300","sheet":"#FFF4DB","cInk":"#141416","cText":"#91680A","short":"The page is an operations board that never stops running.","long":"A departure board under tungsten light: the board is the hero, the headline is a card pinned inside it, ETAs flip like split-flap cells, and a whole shift plays out as you scroll. Pricing is a line-items table.","proves":"A product page where the product is the page.","tags":["Self-playing board","Split-flap cells","Signal amber"],"tk":"software","show":[{"tap":"#chipFilter","say":"Show only the blocked jobs"},{"tap":"#chipAll","say":"Back to the whole board"},{"scrollBy":1600,"dur":3600,"say":"Scroll: the shift plays out"}]},{"n":3,"slug":"maree","kind":"site","lane":"motion","trade":"Fragrance house","mobile":true,"group":"Websites · Motion","name":"MARÉE — Sel Obscur","biz":"Fragrance house","c":"#A9CBBD","sheet":"#F3F8F6","cInk":"#141416","cText":"#63756F","short":"Ink through water, and a page that darkens as you descend.","long":"Salt drawn from a black tide. The ground moves through three marine phases as the notes progress, the bottle is faked entirely in layered SVG, and the whole thing refuses the category’s gold for sea glass.","proves":"Luxury without a single gold gradient.","tags":["Ink canvas","Tone-shifting scroll","SVG glass"],"tk":"creative","show":[{"scrollBy":3200,"dur":6000,"say":"Scroll: the page changes tone"}]},{"n":4,"slug":"signal","kind":"site","lane":"loud","trade":"Festival","mobile":true,"group":"Websites · Loud","name":"SIGNAL 2027","biz":"Music & light festival","c":"#3B18E0","sheet":"#E4DFFB","cInk":"#FFFFFF","cText":"#3B18E0","short":"Type that reacts to how hard you scroll.","long":"Three days of sound, code and light. Marquees whose speed and skew answer your scrolling, headlines that rise into place, an RGB fringe on the display type because the identity is light being split, and a live countdown in enormous tabular numerals.","proves":"Loud, and still not a template.","tags":["Scroll-velocity type","RGB fringe","Live countdown"],"tk":"creative","show":[{"scrollBy":2200,"dur":3800,"say":"Scroll through the festival"},{"tap":"button[data-day=\"1\"]","say":"Filter the line-up by day"}]},{"n":5,"slug":"long-exposure","kind":"site","lane":"motion","trade":"Film production company","mobile":true,"group":"Websites · Motion","name":"Long Exposure","biz":"Long Exposure","c":"#E8A84B","sheet":"#FCF3E6","cInk":"#141416","cText":"#916B35","short":"A film company's site that plays like a film you can scrub.","long":"The page opens on a countdown leader and then runs inside a letterboxed gate with a timecode burned into the corner. Scrolling scrubs the cut; pressing play lets it run on its own; three reels swap the whole shot list. Every frame is drawn in code: no video, no images, nothing to buffer.","proves":"You can show a showreel moving without hosting a single video file.","tags":["scroll-driven","canvas","showreel"],"tk":"creative","show":[{"tap":"#playBtn","say":"Play the cut"},{"wait":5000,"say":"Each reel is a real project"}]},{"n":6,"slug":"overhead","kind":"site","lane":"motion","trade":"Drone survey & filming","mobile":true,"group":"Websites · Motion","name":"Overhead","biz":"Overhead","c":"#B7791F","sheet":"#F5ECE0","cInk":"#141416","cText":"#98661D","short":"Scroll to climb, and the valley draws itself in contours as you rise.","long":"The page is an ascent. Scrolling is altitude: the telemetry counts up, a fictional Peak District dale inks itself in from the valley floor to the tops, and by 120 m the whole view has tilted from an oblique into a flat survey sheet. The map is generated in the browser from one height field, so the contours, the dry-stone walls, the hedgerows and the brook all come out of the same arithmetic.","proves":"A survey outfit can show what it actually hands over instead of a gallery of aerial photos.","tags":["scroll-driven","mapping","before-after"],"tk":"creative","show":[{"scrollBy":1300,"dur":5000,"say":"Scroll to climb: the map draws itself"}]},{"n":7,"slug":"southpaw","kind":"site","lane":"loud","trade":"Boxing club","mobile":true,"group":"Websites · Loud","name":"Southpaw","biz":"Boxing club, Leeds","c":"#C8281E","sheet":"#F7E1E0","cInk":"#FFFFFF","cText":"#C8281E","short":"A boxing club site built as a fight card, run by a round timer.","long":"The hero is a working three-minute round timer (start, pause, reset, twelve rounds with a minute's rest), and every ten seconds it lands another line of the headline like a jab. Classes are laid out as bouts on a fight poster, the timetable is a real weekly grid, and a \"what's on tonight\" row is worked out from the visitor's own clock.","proves":"Somebody who has never boxed can pick a level, pick a night this week and be booked in about twenty seconds.","tags":["Working round timer","Fight-card classes","Live timetable","Free-session flow"],"tk":"gym","show":[{"wait":2500,"say":"The round timer is live"},{"tap":"button[data-level=new]","say":"Book your first session"}]},{"n":8,"slug":"marrow-and-pin","kind":"site","lane":"loud","trade":"Tattoo studio","mobile":true,"group":"Websites · Loud","name":"Marrow & Pin","biz":"Tattoo studio, Bristol","c":"#5B2A86","sheet":"#E8E1EE","cInk":"#FFFFFF","cText":"#5B2A86","short":"A flash wall that inks itself as you scroll past each sheet.","long":"Nine hand-drawn flash designs pinned up as paper sheets, each one drawn twice (a thin purple stencil and the finished black ink), with the ink filling in as the sheet crosses the middle of the screen. Filter the wall by artist, open a sheet for sizes, and the design carries through to a consultation form laid out like the studio's own paperwork, placement picked on a body outline instead of typed into a box.","proves":"Your own drawings can be the website, and they can still take the booking.","tags":["hand-drawn SVG","scroll-driven","booking form"],"tk":"tattoo","show":[{"tap":"button[data-f=joss]","say":"Filter the flash by artist"},{"tap":"button[data-i=\"6\"]","say":"Open a design"}]},{"n":9,"slug":"hale-and-partners","kind":"site","lane":"quiet","trade":"Accountant","mobile":true,"group":"Websites · Quiet","name":"Hale & Partners","biz":"Chartered accountants, Harrogate","c":"#A61E1E","sheet":"#F3E0E0","cInk":"#FFFFFF","cText":"#A61E1E","short":"A year-end that settles, and the deadlines counted from today.","long":"A practice site set out as a well-kept ledger: services written as double entries (what you hand over on the left, what you get back on the right) and a real set of accounts with last year beside this year. The figures count to their values as the statement comes into view and a green tick draws itself beside Filed; the deadline calendar is worked out from the day the visitor opens the page, so it is never out of date.","proves":"The dates and the figures do the selling. Nothing else has to.","tags":["ledger layout","live deadlines","fee request"],"tk":"accountant","show":[{"tap":"button[data-v=ltd]","say":"Say what you run"},{"tap":"button[data-v=dead]","say":"And what is worrying you"},{"tap":"button[data-v=cloud]","say":"They tell you where they would start"}]},{"n":10,"slug":"fern-physio","kind":"site","lane":"quiet","trade":"Physiotherapy clinic","mobile":true,"group":"Websites · Quiet","name":"Fern Physio","biz":"Fern Physio","c":"#6F8F79","sheet":"#EBEFEC","cInk":"#141416","cText":"#5E7866","short":"A drawn body with ten tappable points, and a booking flow behind it.","long":"A two-room physiotherapy clinic where the hero is a hand-drawn standing figure, front and back, with ten points you can tap. Each one names what the problem usually turns out to be, what the physio would actually do about it, and books that assessment in four questions. The diary is generated from the real clock, so the slots are never stale.","proves":"A visitor can say where it hurts before they have to say anything to a receptionist.","tags":["quiet","booking","drawn SVG"],"tk":"clinic","show":[{"tap":"button[data-r=knee]","say":"Tap where it hurts"}]},{"n":11,"slug":"kestrel-electrical","kind":"site","lane":"direct","trade":"Electrician","mobile":true,"group":"Websites · Direct","name":"Kestrel Electrical","biz":"Two-van electrical firm","c":"#6B3A1E","sheet":"#EAE3E0","cInk":"#FFFFFF","cText":"#6B3A1E","short":"An electrician's page built as a fuse board: every job is a breaker.","long":"Three lines say what they do, where they go and when they answer; under them sit three fields and the phone number at poster size. The services are a row of breakers on a board: flip one and it turns on to show what's included, what it costs and a button to ring about it. The only thing that moves on the page is a switch.","proves":"Someone standing in a dark kitchen can ring the right number in one tap, at any hour, without reading a word of marketing.","tags":["Breaker board","Three-field callback","Postcode area check","Open-now line switching"],"tk":"electrician","show":[{"tap":"button[data-k=ev]","say":"Flip a breaker"},{"tap":"button[data-k=emergency]","say":"The emergency one"}]},{"n":12,"slug":"kerb-and-camber","kind":"site","lane":"direct","trade":"Garage","mobile":true,"group":"Websites · Direct","name":"Kerb & Camber","biz":"Kerb & Camber MOT Centre","c":"#1F4E9C","sheet":"#E0E6F1","cInk":"#FFFFFF","cText":"#1F4E9C","short":"A UK number plate you type into, and the MOT date that comes back.","long":"An independent MOT and service centre where the hero is a real number plate you can type in. Press Check and a job card slides in with the vehicle, the last advisory, how many days until the MOT runs out, and the next three slots on the ramp. The price board, the tyre-size helper and the opening hours are all on the same page, and the phone number never leaves the screen on a mobile.","proves":"Somebody who does not know when their MOT is due can find out and book it before they close the tab.","tags":["direct","reg lookup","booking"],"tk":"garage","show":[{"type":"#reg","text":"KX19 LBD","say":"Put your reg in"},{"tap":"#checkBtn","say":"It tells you when the MOT is due"}]},{"n":13,"slug":"system","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"The system","biz":"Six made-up service businesses","c":"#B04A24","sheet":"#F4E6E0","cInk":"#FFFFFF","cText":"#B04A24","short":"One screen: every call caught, every job booked, and what still needs you.","long":"The app a service business runs on, shown for six made-up businesses. Today shows every missed call caught, every booking made and every quote chased since the morning, the next jobs, and the three things that still need a person. Switch business from the menu and it all reloads for that trade.","proves":"The admin happens while you are on the tools.","tags":["Six businesses","Live from the clock","Every part connected"],"tk":"any","show":[{"tap":"#todaySim","say":"A call rings out while you are on a job","pause":400},{"wait":7000,"say":"The system texts them back in seconds"},{"wait":5000,"say":"They reply, and it is all in the inbox"}]},{"n":14,"slug":"inbox","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"Inbox and missed calls","biz":"Six made-up service businesses","c":"#B04A24","sheet":"#F4E6E0","cInk":"#FFFFFF","cText":"#B04A24","short":"Every call, text and form in one list. Missed calls get a text back in seconds.","long":"Press “Simulate a missed call” and watch it happen: the phone rings out, a countdown runs, the text goes from the business’s own number, and the customer replies. One tap sends the booking link, and the booking lands in the diary with its deposit.","proves":"The customer gets a text before they ring the next name on Google.","tags":["Missed-call text-back","One inbox","Booking link"],"tk":"any","show":[{"tap":"#simCall","say":"Simulate a missed call","pause":400},{"wait":7000,"say":"A text goes back in seconds, from the business’s own number"},{"wait":4500,"say":"They reply"},{"tap":"#inLink","say":"One tap sends the booking link","pause":400},{"wait":5500,"say":"They book and pay the deposit"}]},{"n":15,"slug":"booking","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"Booking and the diary","biz":"Six made-up service businesses","c":"#B04A24","sheet":"#F4E6E0","cInk":"#FFFFFF","cText":"#B04A24","short":"Customers book a real free time and pay a deposit. It lands in the right diary.","long":"A diary with a lane for each person, travel time between jobs, and the deposit on every online booking. Book as a customer from their phone and watch the slot appear; move a job, send an on-my-way text, or mark it done and the review ask queues itself.","proves":"Nobody books and vanishes, and nobody plays phone tag for a time.","tags":["Online booking","Deposits","Team diary"],"tk":"any","show":[{"tap":"#bkTry","say":"Book online, as a customer would"},{"tap":".bk-po","say":"Pick the job","pause":600},{"tap":"#bkT-0","say":"Pick a free time","pause":600},{"tap":"#bkPay","say":"Pay the deposit","pause":1200},{"tap":"#bkDone","say":"It is in the diary, marked new"}]},{"n":16,"slug":"quotes","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"Quotes that chase themselves","biz":"Six made-up service businesses","c":"#B04A24","sheet":"#F4E6E0","cInk":"#FFFFFF","cText":"#B04A24","short":"Quotes from your price list that chase themselves until the customer answers.","long":"Quotes built from the business’s own price list with VAT and a deposit. Send one and watch it get opened; it chases at 9am on day two and day five until the customer answers, then stops the moment they accept and pay the deposit.","proves":"Fewer quotes go cold while you are busy.","tags":["Price list","Automatic chasing","Accept and pay"],"tk":"any","show":[{"tap":"#qNew","say":"Start a quote from your own template"},{"tap":"#qSend","say":"Send it: the customer gets a link","pause":400},{"wait":4500,"say":"Opened, and the chasing is booked in"},{"tap":"#qPhone","say":"What the customer sees"},{"tap":"#qAccept","say":"They accept and pay the deposit. The chasing stops."}]},{"n":17,"slug":"reviews","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"Google reviews","biz":"Six made-up service businesses","c":"#B04A24","sheet":"#F4E6E0","cInk":"#FFFFFF","cText":"#B04A24","short":"Every finished job asks for a review. Replies take one tap.","long":"After each job the customer gets a short text with a link to leave a Google review. Every customer is asked, not only the happy ones, because Google’s rules ban picking. New reviews land here with a reply already written to edit and post.","proves":"More reviews, and recent ones, keep you near the top of the map.","tags":["Review asks","One-tap replies","Rating over time"],"tk":"any","show":[{"tap":"#rvSend","say":"Every finished job gets a review text","pause":400},{"wait":6500,"say":"A new five-star review lands"},{"tap":"#rvList [data-act=reply]","say":"The reply is drafted with their name and the job"},{"tap":"#rvPost","say":"Post it"}]},{"n":18,"slug":"reminders","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"Reminders that rebook","biz":"Six made-up service businesses","c":"#B04A24","sheet":"#F4E6E0","cInk":"#FFFFFF","cText":"#B04A24","short":"Yearly services, MOTs and regular cuts remind the customer and book themselves.","long":"Repeat work comes round on its own: the boiler service, the MOT, the six-weekly cut. The customer gets a reminder before it is due and books from the link; the booking drops into the diary without a phone call.","proves":"Last year’s customers come back before they search.","tags":["Due dates","Reminder texts","Rebooked jobs"],"tk":"any","show":[{"tap":"#rmSend","say":"Reminders go out before the work is due","pause":400},{"wait":5500,"say":"Customers book themselves in from the text"},{"tap":"#rmList .rm-row","say":"Each one: the text, its history and the free times"}]},{"n":19,"slug":"results","kind":"tool","lane":"system","trade":"Any service business","mobile":true,"group":"The system","name":"Results and ads","biz":"Six made-up service businesses","c":"#B04A24","sheet":"#F4E6E0","cInk":"#FFFFFF","cText":"#B04A24","short":"Where every job came from, what it was worth, and what the ads cost per job.","long":"A month-by-month view of where the work came from: Google Ads, Meta ads, the map, the website, referrals and repeat customers, with enquiries, bookings, the money booked and the cost per job. The monthly report writes itself in plain English. Demo figures for a made-up business.","proves":"You can see which pound of ad spend booked which job.","tags":["By source","Cost per job","Monthly report"],"tk":"any","show":[{"tap":"#rsMonth [data-i=\"4\"]","say":"Pick a month"},{"scroll":"#rsChain","say":"From enquiry to booked work"},{"tap":"#rsReport","say":"The monthly report, in plain English"}]}];